def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    last_me, last_opp = history[-1]
    if n == 2:
        if last_opp == 'D':
            return 'D'
        return 'C'
    opp_def = 0
    my_def = 0
    cc = 0
    cd = 0
    dc = 0
    dd = 0
    for i in range(n):
        m, o = history[i]
        if m == 'C':
            if o == 'C':
                cc += 1
            else:
                cd += 1
                opp_def += 1
        else:
            my_def += 1
            if o == 'C':
                dc += 1
            else:
                dd += 1
                opp_def += 1
    if n >= 95:
        if opp_def * 2 < n:
            return 'D'
        if last_opp == 'C' and (n < 2 or history[-2][1] == 'C'):
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'
    recent10 = history[-10:] if n >= 10 else history
    r10_opp_def = 0
    for i in range(len(recent10)):
        if recent10[i][1] == 'D':
            r10_opp_def += 1
    if n >= 10:
        if r10_opp_def >= 8:
            if last_opp == 'D':
                return 'D'
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        if r10_opp_def >= 6:
            if last_opp == 'D':
                return 'D'
            if rng.random() < 0.4:
                return 'D'
            return 'C'
    if n >= 20:
        r20_opp_def = 0
        for i in range(n - 20, n):
            if history[i][1] == 'D':
                r20_opp_def += 1
        if r20_opp_def >= 14:
            return 'D'
        if r20_opp_def <= 1:
            if last_me == 'D':
                return 'C'
            if n >= 60 and n % 13 == 0 and dc < dd:
                return 'D'
            return 'C'
    if last_opp == 'D':
        if last_me == 'D':
            if n >= 3 and history[-2][1] == 'D' and history[-2][0] == 'D':
                if rng.random() < 0.85:
                    return 'D'
                return 'C'
            if rng.random() < 0.6:
                return 'D'
            return 'C'
        else:
            streak = 0
            for i in range(n - 1, -1, -1):
                if history[i][1] == 'D':
                    streak += 1
                else:
                    break
            if streak >= 3:
                return 'D'
            if opp_def * 3 < n:
                if rng.random() < 0.35:
                    return 'C'
                return 'D'
            if rng.random() < 0.6:
                return 'D'
            return 'C'
    else:
        if last_me == 'D':
            if dc >= 3 and dd == 0 and n < 90:
                if rng.random() < 0.25:
                    return 'D'
            return 'C'
        streak_c = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'C':
                streak_c += 1
            else:
                break
        if streak_c >= 6 and n < 88:
            if dc > 0 and rng.random() < 0.06:
                return 'D'
            return 'C'
        if opp_def == 0 and n >= 30:
            if n < 90 and n % 17 == 0:
                if rng.random() < 0.3:
                    return 'D'
            return 'C'
        return 'C'
